But `go:generate` in greeter.go would generate to a _test.go file. That's fine.

Let me write greeter.go and a test.

Test using gomock + testify:
```go
package greeter

import (
    "context"
    "errors"
    "testing"

    "github.com/stretchr/testify/assert"
    "github.com/stretchr/testify/require"
    "go.uber.org/mock/gomock"
)

func TestGreeter_Greet(t *testing.T) {
    tests := []struct{
        name string
        hour int
        want string
    }{
        {"morning", 9, "Good morning, Ada!"},
        {"afternoon", 14, "Good afternoon, Ada!"},
        {"evening", 21, "Good evening, Ada!"},
    }
    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            ctrl := gomock.NewController(t)
            clock := NewMockClock(ctrl)
            clock.EXPECT().Hour(gomock.Any()).Return(tt.hour, nil).Times(1)

            got, err := New(clock).Greet(context.Background(), "Ada")
            require.NoError(t, err)
            assert.Equal(t, tt.want, got)
        })
    }
}

func TestGreeter_Greet_error(t *testing.T) {
    ctrl := gomock.NewController(t)
    clock := NewMockClock(ctrl)
    clock.EXPECT().Hour(gomock.Any()).Return(0, errors.New("clock down"))

    _, err := New(clock).Greet(context.Background(), "Ada")
    require.Error(t, err)
    assert.ErrorContains(t, err, "clock down")
}
```

Note: in Go 1.14+, gomock.NewController(t) auto-calls Finish via t.Cleanup, so no defer needed.

